1	/* 單行時高度由 min-height 決定（PR-STYLE-55），上下內距取最小階，文字換行時才撐高（PR-STYLE-56）；元件自帶 border-box，不依賴使用端的全域重設。
2	   長字串可在任意處斷開；為了不讓 flex 列把短標籤擠到斷字，按鈕不收縮，改以 max-width 限制在容器內。
3	   渲染成連結時（PR-STYLE-58）拿掉連結底線，外觀與按鈕相同。 */
4	.luca-button { box-sizing:border-box; text-decoration:none; overflow-wrap:anywhere; flex-shrink:0; max-width:100%; display:inline-flex; align-items:center; justify-content:center; gap:var(--space-3); min-height:var(--control-height); padding:var(--space-1) var(--space-6); border:var(--border-width) solid var(--border); border-radius:var(--radius-control); background:var(--accent); color:var(--accent-ink); font:500 1rem/1.5 var(--font-body); cursor:pointer; }
5	/* 滑過、按下用推算出的強調色角色（PR-STYLE-45），不再用 brightness 濾鏡。 */
6	/* 會收到專案 className 的元素，狀態選擇器都包進 :where()，特異度維持 (0,1,0)，專案的 class 才能生效（PR-ADOPT-05）。:focus-visible 例外，見檔尾。 */
7	.luca-button-primary:where(:not(:disabled):hover) { background:var(--accent-hover); }
8	.luca-button-primary:where(:not(:disabled):active) { background:var(--accent-pressed); }
9	.luca-button:where(:disabled) { opacity:.5; cursor:not-allowed; }
10	[data-luca-theme] { min-height:100vh; background:var(--bg); color:var(--text); transition:background-color var(--motion-standard), color var(--motion-standard); }
11	.luca-button { transition:background-color var(--motion-feedback), border-color var(--motion-feedback), color var(--motion-feedback); }
12	@media (prefers-reduced-motion: reduce) { [data-luca-theme], [data-luca-theme] *, [data-luca-theme] *::before, [data-luca-theme] *::after { animation:none !important; transition:none !important; scroll-behavior:auto !important; } }
13	.luca-button-secondary { background:var(--surface); color:var(--accent); border-color:var(--accent); }
14	.luca-button-secondary:where(:not(:disabled):hover) { color:var(--accent-hover); border-color:var(--accent-hover); }
15	.luca-button-secondary:where(:not(:disabled):active) { color:var(--accent-pressed); border-color:var(--accent-pressed); }
16	.luca-field { display:grid; gap:var(--space-2); min-width:0; }
17	.luca-field > label { font:500 1rem/1.5 var(--font-body); overflow-wrap:anywhere; }
18	.luca-input { box-sizing:border-box; width:100%; min-width:0; min-height:var(--control-height); padding:var(--space-1) var(--space-4); font:500 1rem/1.5 var(--font-body); color:var(--text); background:var(--surface); border:1px solid var(--control-border); border-radius:var(--radius-control); }
19	.luca-input:where([aria-invalid=true]) { border-color:var(--error); }
20	.luca-input:where(:disabled) { opacity:.6; cursor:not-allowed; }
21	/* Select 欄位與選單，對照元件庫母版 C/Select/Open 與前端規格 §5.5.2。 */
22	.luca-select-trigger { display:flex; align-items:center; gap:var(--space-3); text-align:left; cursor:pointer; }
23	/* 停用游標要排在上一行之後：:where() 讓 .luca-input 的停用規則與上一行特異度相同，只能靠順序。 */
24	.luca-select-trigger:where(:disabled) { cursor:not-allowed; }
25	.luca-select-value { flex:1; min-width:0; overflow-wrap:anywhere; }
26	.luca-select-icon { display:flex; flex:none; color:var(--muted); }
27	.luca-select-positioner { z-index:10; outline:0; }
28	/* 選單與欄位同寬（--anchor-width 由 Base UI 提供）；陰影取自母版的 0 8px 24px、文字色 12%。 */
29	.luca-select-popup { box-sizing:border-box; display:grid; gap:2px; width:var(--anchor-width); max-height:var(--available-height); overflow-y:auto; padding:var(--space-1); background:var(--surface); color:var(--text); border:var(--border-width) solid var(--border); border-radius:var(--radius-control); box-shadow:0 8px 24px rgba(36,49,42,.12); outline:0; }
30	.luca-select-option { box-sizing:border-box; display:flex; align-items:center; min-height:40px; padding:var(--space-1) var(--space-3); overflow-wrap:anywhere; border-radius:var(--radius-control); font:var(--type-control-weight) var(--type-control-size)/var(--type-control-line-height) var(--font-body); cursor:pointer; outline:0; }
31	/* 滑過與鍵盤目前項目同為 data-highlighted；選中項以柔和強調表面加粗、不加打勾。 */
32	.luca-select-option[data-highlighted] { background:var(--surface-subtle); }
33	.luca-select-option[data-selected] { background:var(--accent-soft); font-weight:700; }
34	.luca-select-option[data-disabled] { color:var(--muted); cursor:not-allowed; }
35	.luca-field-helper, .luca-field-error { font:400 .875rem/1.6 var(--font-body); overflow-wrap:anywhere; }
36	.luca-field-helper { color:var(--muted); }
37	.luca-field-error { color:var(--error); }
38	/* position:relative 讓 hideLabel 的隱藏文字留在列內，不撐出外層的捲動範圍。 */
39	.luca-checkbox { position:relative; display:flex; gap:var(--space-3); align-items:center; min-height:var(--control-height); cursor:pointer; }
40	.luca-checkbox-box { display:flex; flex:none; align-items:center; justify-content:center; box-sizing:border-box; width:1.25rem; height:1.25rem; margin:0; padding:0; border:1px solid var(--control-border); border-radius:calc(var(--radius-control) / 2); background:var(--surface); color:var(--accent-ink); cursor:pointer; }
41	/* 勾選或不確定時填主色，打勾圖示用填色按鈕的文字色；未勾選時圖示不渲染。 */
42	.luca-checkbox-box:where([data-checked], [data-indeterminate]) { background:var(--accent); border-color:var(--accent); }
43	.luca-checkbox-box:where([aria-invalid=true]) { border-color:var(--error); }
44	.luca-checkbox-box:where([data-disabled]) { opacity:.6; cursor:not-allowed; }
45	/* hideLabel 的標籤文字：視覺上隱藏但留在無障礙樹內，不可改成 display:none 或 visibility:hidden。
46	   方框列是它的定位容器（見 .luca-checkbox 的 position），絕對定位不參與 flex，列高與間距不變。 */
47	.luca-visually-hidden { position:absolute; width:1px; height:1px; padding:0; margin:-1px; border:0; overflow:hidden; clip:rect(0 0 0 0); clip-path:inset(50%); white-space:nowrap; }
48	.luca-checkbox-indicator { display:flex; }
49	.luca-checkbox-indicator[data-unchecked] { display:none; }
50	.luca-status { padding:var(--space-3) var(--space-4); border:1px solid currentColor; border-radius:var(--radius-control); background:var(--surface); font:400 .875rem/1.6 var(--font-body); overflow-wrap:anywhere; }
51	.luca-status-success { color:var(--success); } .luca-status-warning { color:var(--warning); } .luca-status-error { color:var(--error); }
52	.luca-content-state { padding:var(--card-padding); border:var(--border-width) solid var(--border); border-radius:var(--radius-card); background:var(--surface); min-width:0; }
53	.luca-content-state h3 { margin:0; color:var(--text); font:600 1.125rem/1.5 var(--font-body); }
54	/* 外距與底線寫明瀏覽器預設值，Tailwind 的 preflight 才不會歸零（PR-ADOPT-05）。 */
55	.luca-content-state p { margin:1em 0; color:var(--muted); font:400 .875rem/1.6 var(--font-body); }
56	.luca-loading-animation { display:block; width:72px; height:72px; margin-bottom:var(--space-3); background:var(--loading-animation,url('../loading/tide-light.gif')) center/contain no-repeat; }
57	[data-luca-theme][data-suite="vibrant"][data-mode="light"] { --loading-animation:url('../loading/tide-light.gif'); --loading-static:url('../loading/tide-light.png'); }
58	[data-luca-theme][data-suite="vibrant"][data-mode="dark"] { --loading-animation:url('../loading/tide-dark.gif'); --loading-static:url('../loading/tide-dark.png'); }
59	[data-luca-theme][data-suite="professional"][data-mode="light"] { --loading-animation:url('../loading/square-light.gif'); --loading-static:url('../loading/square-light.png'); }
